export interface AttachmentDisplayResolvers {
  /** Resolves the image preview URL for an attachment that has a remote `url`. */
  resolvePreviewUrl?(dto: MessageAttachment): string | undefined;
  /** Resolves the audio playback URL for an attachment that has a remote `url`. */
  resolvePlayUrl?(dto: MessageAttachment): string | undefined;
}

messageAttachmentToDisplayAttachment = (
  dto: MessageAttachment,
  resolvers: AttachmentDisplayResolvers = {},
): DisplayAttachment => {
  const type = getAttachmentTypeFromMime(dto.type);
  const isImage = type === AttachmentType.Image;
  const isAudio = type === AttachmentType.Audio;
  const isLink = dto.url && dto.reference_url && !dto.reference_type;
  const id = dto.url ?? dto.data ?? dto.title;

  const contentType =
    (dto.url == null && dto.reference_url != null
      ? (dto.reference_type ?? inferMimeTypeFromPath(dto.reference_url))
      : undefined) ??
    dto.type ??
    '';

  let previewUrl: string | undefined;
  if (isImage) {
    if (dto.url) {
      previewUrl = resolvers.resolvePreviewUrl?.(dto) ?? dto.url;
    } else if (dto.data) {
      previewUrl = getInlineDataUrl(dto.type, dto.data, 'image/');
    }
  }

  let playUrl: string | undefined;
  if (isAudio) {
    if (dto.url) {
      playUrl = resolvers.resolvePlayUrl?.(dto) ?? dto.url;
    } else if (dto.data) {
      playUrl = getInlineDataUrl(dto.type, dto.data, 'audio/');
    }
  }

  return {
    id,
    name: dto.title,
    contentType,
    type: isLink ? AttachmentType.Link : type,
    status: RequestStatus.Idle,
    ...(dto.url ? { url: dto.url } : {}),
    ...(dto.reference_url ? { referenceUrl: dto.reference_url } : {}),
    ...(isImage && previewUrl ? { previewUrl } : {}),
    ...(isAudio && playUrl ? { playUrl } : {}),
    ...(!isImage && !isAudio && dto.data ? { data: dto.data } : {}),
  };
}

messageAttachmentsToDisplayAttachments = (
  dtos: MessageAttachment[] | undefined,
  resolvers: AttachmentDisplayResolvers = {},
): DisplayAttachment[] => {
  const seen = new Set<string | undefined>();
  return (
    dtos?.reduce<DisplayAttachment[]>((acc, dto) => {
      const att = messageAttachmentToDisplayAttachment(dto, resolvers);
      if (!seen.has(att.id)) {
        seen.add(att.id);
        acc.push(att);
      }
      return acc;
    }, []) ?? []
  );
}

inferMimeTypeFromPath = (path: string): MIMEType | undefined => {
  const clean = stripUrlQueryAndFragment(path);
  const dotIdx = clean.lastIndexOf('.');
  if (dotIdx === -1) return undefined;
  const ext = clean.slice(dotIdx + 1).toLowerCase();
  return EXTENSION_TO_MIME_TYPE[ext];
}

getAttachmentTypeFromMime = (
  mimeType: string | undefined,
): AttachmentType => {
  if (mimeType?.startsWith('image/')) return AttachmentType.Image;
  if (mimeType?.startsWith('audio/')) return AttachmentType.Audio;
  return AttachmentType.File;
}

copyMarkdownAsRichText = (content: string): Promise<boolean> => {
  if (
    typeof navigator === 'undefined' ||
    !navigator.clipboard?.write ||
    typeof ClipboardItem === 'undefined'
  ) {
    return copyToClipboard(content);
  }

  let html: string;
  try {
    html = markdownToRichTextHtml(content);
  } catch {
    return copyToClipboard(content);
  }

  /*
   * Both flavours ride along. A rich target picks `text/html` — that is the
   * negotiation every editor implements, and the styling arrives as before —
   * while a plain-text target, which can read nothing but `text/plain`, would
   * otherwise paste an empty string. `onCopyMarkdown` still exists for the
   * deliberate markdown-only copy; this action is simply no longer unusable
   * outside a rich editor.
   *
   * Clipboard API must be called synchronously within the user-gesture
   * handler; do NOT await before calling it.
   */
  return navigator.clipboard
    .write([
      new ClipboardItem({
        'text/html': new Blob([html], { type: 'text/html' }),
        'text/plain': new Blob([content], { type: 'text/plain' }),
      }),
    ])
    .then(() => true)
    .catch(() => copyToClipboard(content));
}

copyToClipboard = (text: string): Promise<boolean> => {
  if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
    /*
     * Clipboard API must be called synchronously within the user-gesture
     * handler; do NOT await before calling it.
     */
    return navigator.clipboard
      .writeText(text)
      .then(() => true)
      .catch(() => execCommandFallback(text));
  }
  return Promise.resolve(execCommandFallback(text));
}

formatLastUsed = (timestamp?: number): string => {
  if (!timestamp) return '';

  const date = new Date(timestamp);
  if (isNaN(date.getTime())) return '';

  const diffMs = Date.now() - date.getTime();
  const diffSec = Math.floor(diffMs / 1000);

  if (diffSec < 60) return 'just now';

  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin} min ago`;

  const diffHours = Math.floor(diffMin / 60);
  if (diffHours < 24)
    return `${diffHours} hour${diffHours === 1 ? '' : 's'} ago`;

  const diffDays = Math.floor(diffHours / 24);
  if (diffDays < 30) return `${diffDays} day${diffDays === 1 ? '' : 's'} ago`;

  const diffMonths = Math.floor(diffDays / 30);
  if (diffMonths < 12)
    return `${diffMonths} month${diffMonths === 1 ? '' : 's'} ago`;

  const diffYears = Math.floor(diffMonths / 12);
  return `${diffYears} year${diffYears === 1 ? '' : 's'} ago`;
}

formatFileSize = (bytes: number): string => {
  if (bytes >= GB)
    return `${(bytes / GB).toFixed(bytes % GB === 0 ? 0 : 1)} GB`;
  if (bytes >= MB)
    return `${(bytes / MB).toFixed(bytes % MB === 0 ? 0 : 1)} MB`;
  if (bytes >= KB)
    return `${(bytes / KB).toFixed(bytes % KB === 0 ? 0 : 1)} KB`;
  return `${bytes} B`;
}

formatPrice = (value: number): string => {
  if (value !== 0 && Math.abs(value) < 1) {
    return smallPriceFormatter.format(value);
  }
  return formatCost(value);
}

formatUnitPrice = (
  price: string | undefined,
  unit: string | undefined,
): string | undefined => {
  if (price == null) return undefined;

  const perUnit = Number(price);
  if (price.trim() === '' || !Number.isFinite(perUnit)) return price;

  if (unit == null || unit.toLowerCase() === TOKEN_PRICING_UNIT) {
    return `${formatPrice(perUnit * TOKENS_PER_QUOTED_PRICE)}/M tokens`;
  }

  return `${formatPrice(perUnit)}/${unit.replace(/_/g, ' ')}`;
}

ensureDownloadFilename = (
  name: string,
  url: string | undefined,
  contentType: string | undefined,
): string => {
  if (extractPlausibleExtension(name) != null) return name;

  if (contentType != null) {
    const ext = MIME_TYPE_EXT_MAP[contentType];
    if (ext != null) return `${name}.${ext}`;
  }

  if (url != null) {
    const segment = stripUrlQueryAndFragment(url).split('/').pop() ?? '';
    const ext = extractPlausibleExtension(segment);
    if (ext != null) return `${name}.${ext}`;
  }

  return name;
}

triggerAnchorDownload = (href: string, filename: string): void => {
  const anchor = document.createElement('a');
  anchor.href = href;
  anchor.download = filename;
  anchor.rel = 'noopener';
  anchor.style.display = 'none';
  /* The anchor must be in the document: a detached one is ignored by Firefox
   * and Safari, which drops the download without any error. */
  document.body.appendChild(anchor);
  anchor.click();
  setTimeout(() => anchor.remove(), DOWNLOAD_CLEANUP_DELAY_MS);
}

triggerBlobDownload = (blob: Blob, filename: string): void => {
  const url = URL.createObjectURL(blob);
  triggerAnchorDownload(url, filename);
  setTimeout(() => URL.revokeObjectURL(url), DOWNLOAD_CLEANUP_DELAY_MS);
}

tryBase64ToBytes = (base64: string): Uint8Array | undefined => {
  try {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  } catch {
    return undefined;
  }
}

base64ToBlob = (data: string, mimeType: string): Blob => {
  const bytes = tryBase64ToBytes(data) ?? new TextEncoder().encode(data);
  return new Blob([bytes.buffer as ArrayBuffer], { type: mimeType });
}

downloadTextFile = (
  content: string,
  filename: string,
  mimeType = 'text/plain;charset=utf-8',
): void => {
  triggerBlobDownload(new Blob([content], { type: mimeType }), filename);
}

