extractInitials = (name: string): string => {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return '?';

  if (words.length >= 2) {
    const initials = (
      firstLetter(words[0]) + firstLetter(words[1])
    ).toUpperCase();
    return initials || '?';
  }

  const letters = words[0].replace(/[^\p{L}]/gu, '');
  return letters.slice(0, 2).toUpperCase() || '?';
}

export interface AvatarColorEntry {
  /** CSS colour value for the badge background — a theme token with a hex fallback. */
  background: string;
  /** CSS colour value for the initials text — a theme token with a hex fallback. */
  foreground: string;
}

pickAvatarColor = (name: string): AvatarColorEntry => {
  let sum = 0;
  for (let i = 0; i < name.length; i++) {
    sum += name.charCodeAt(i);
  }
  return PALETTE[sum % PALETTE.length];
}

