defaultMarkdownComponents: Components = {
  li: ({ children }) => <li className="mb-1.5 last:mb-0">{children}</li>,
  ...({ cit: renderCitTagAsText } as Components),
}

MarkdownRenderer: FC<MarkdownRendererProps> = memo(
  ({
    content,
    containerClassName,
    isStreaming,
    streamCharactersPerSecond,
    classNames = EMPTY_CLASS_NAMES,
    components,
    urlTransform,
    rehypePlugins = EMPTY_REHYPE_PLUGINS,
    thinkingLabel = 'Thinking',
    codeBlockCopyLabel,
    codeBlockCopiedLabel,
    codeBlockTheme,
    colors,
    tableActionLabels,
    tableDownloadFilename,
    tableOnOpenInCanvas,
    tableScrollRegionAriaLabel,
    mathScrollRegionAriaLabel,
  }) => {
    const displayedContent = useStreamedMarkdownContent(
      content,
      isStreaming,
      streamCharactersPerSecond,
    );
    const processedContent = useMemo(
      () => preprocessLaTeX(displayedContent),
      [displayedContent],
    );

    const needsMath = useMemo(
      () => hasMathContent(processedContent),
      [processedContent],
    );

    const [katexPlugin, setKatexPlugin] = useState<
      NonNullable<Options['rehypePlugins']>[number] | null
    >(null);

    /*
     * KaTeX and its stylesheet are loaded on demand, the first time a message
     * actually contains a math block, so plain-text/code-only conversations
     * never pull the ~150 KB engine into the initial bundle.
     */
    useEffect(() => {
      if (!needsMath || katexPlugin) return;

      let cancelled = false;
      const loadKatex = async () => {
        const [katexModule] = await Promise.all([
          import('rehype-katex'),
          import('katex/dist/katex.min.css'),
        ]);
        if (!cancelled) {
          setKatexPlugin([
            katexModule.default,
            { output: 'mathml', strict: false },
          ]);
        }
      };
      void loadKatex();

      return () => {
        cancelled = true;
      };
    }, [needsMath, katexPlugin]);

    /*
     * Pipeline order matters: raw HTML is re-parsed first, KaTeX (once loaded)
     * turns math spans into MathML, and sanitization runs last over everything
     * both passes produced.
     */
    const effectiveRehypePlugins = useMemo(
      () => [
        ...preKatexRehypePlugins,
        ...(katexPlugin ? [katexPlugin] : []),
        sanitizeRehypePlugin,
        ...rehypePlugins,
      ],
      [katexPlugin, rehypePlugins],
    );

    const cssVars = buildCssVars({
      '--cm-thinking-inverted': colors?.thinkingPrimary,
      '--cm-thinking-secondary': colors?.thinkingSecondary,
      '--cm-markdown-border': colors?.border,
      '--cm-blockquote-border': colors?.blockquoteBorder,
      '--cm-blockquote-text': colors?.blockquoteText,
      '--cm-link-text': colors?.linkText,
      '--cm-link-focus': colors?.linkFocus,
      '--cm-table-header-text': colors?.tableHeaderText,
      '--cm-h6-text': colors?.headingSixText,
      '--cm-code-inline-bg': colors?.inlineCodeBackground,
      '--cm-code-inline-text': colors?.inlineCodeText,
    });

    const effectiveUrlTransform = useMemo(
      () => composeUrlTransform(urlTransform),
      [urlTransform],
    );

    const mergedComponents = useMemo(
      () => ({
        ...buildMarkdownComponents(classNames, {
          isStreaming,
          codeBlockCopyLabel,
          codeBlockCopiedLabel,
          codeBlockTheme,
          tableActionLabels,
          tableDownloadFilename,
          tableOnOpenInCanvas,
          tableScrollRegionAriaLabel,
          mathScrollRegionAriaLabel,
        }),
        ...defaultMarkdownComponents,
        ...components,
      }),
      [
        classNames,
        isStreaming,
        codeBlockCopyLabel,
        codeBlockCopiedLabel,
        codeBlockTheme,
        tableActionLabels,
        tableDownloadFilename,
        tableOnOpenInCanvas,
        tableScrollRegionAriaLabel,
        mathScrollRegionAriaLabel,
        components,
      ],
    );

    if (isStreaming && !displayedContent) {
      return (
        <span className={styles.thinking} style={cssVars}>
          {thinkingLabel}
        </span>
      );
    }

    return (
      <div style={cssVars} className={containerClassName}>
        <ReactMarkdown
          remarkPlugins={remarkPlugins}
          rehypePlugins={effectiveRehypePlugins}
          components={mergedComponents}
          urlTransform={effectiveUrlTransform}
        >
          {processedContent}
        </ReactMarkdown>
      </div>
    );
  },
)

MDMessageViewer: FC<MDMessageViewerProps> = memo(
  ({
    content,
    isStreaming,
    thinkingLabel,
