MarkdownCodeBlock: FC<MarkdownCodeBlockProps> = memo(
  ({
    language,
    value,
    isStreaming,
    theme = CodeBlockTheme.Dark,
    copyLabel = 'Copy code',
    copiedLabel = 'Copied!',
    downloadLabel = 'Download code',
    hideDownload = false,
    containerClassName,
    headerClassName,
    codeClassName = 'dial-code-text',
    languageLabelClassName = 'dial-tiny-lead-semi-text',
    title,
    titleSlot,
    colors,
  }) => {
    const { isCopied, copy } = useCodeCopy(value);
    const isLightTheme = theme === CodeBlockTheme.Light;
    const handleDownload = () => {
      downloadTextFile(value, `code.${getFileExtensionForLanguage(language)}`);
    };
    /* Rendered for language-less blocks, and as the Suspense fallback while
     * the syntax-highlighting engine loads for a language-tagged block. */
    const plainCode = (
      <pre className="p-4">
        <code className={mergeClasses('whitespace-pre', codeClassName)}>
          {value}
        </code>
      </pre>
    );
    const cssVars = buildCssVars({
      '--cm-code-block-bg': colors?.background,
      '--cm-code-block-border': colors?.border,
      '--cm-code-block-header-bg': colors?.headerBackground,
      '--cm-code-block-language': colors?.language,
      '--cm-code-block-copied': colors?.copied,
      '--cm-code-block-scrollbar': colors?.scrollbar,
    });

    return (
      <div
        style={cssVars}
        className={mergeClasses(
          'my-4 max-w-full rounded-xl border [overflow:clip]',
          styles.container,
          isLightTheme && styles.containerLight,
          containerClassName,
          CHAT_SHARED_CLASS.codeBlock,
        )}
      >
        <div
          className={mergeClasses(
            'sticky top-0 z-10 flex min-h-10 items-center justify-between px-4',
            titleSlot != null ? 'py-0' : 'py-2',
            styles.header,
            headerClassName,
            CHAT_SHARED_CLASS.codeBlockHeader,
          )}
        >
          {titleSlot ?? (
            <span
              className={mergeClasses(
                styles.languageLabel,
                languageLabelClassName,
              )}
            >
              {title ?? language}
            </span>
          )}
          {!isStreaming && (
            <div className="flex items-center gap-1">
              {!hideDownload && (
                <GhostIconButton
                  icon={
                    <IconDownload
                      size={DIAL_ICON_SIZE.SM}
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  }
                  aria-label={downloadLabel}
                  size={ElementSize.Small}
                  onClick={handleDownload}
                />
              )}
              <GhostIconButton
                icon={
                  isCopied ? (
                    <IconCheck
                      size={DIAL_ICON_SIZE.SM}
                      className={styles.copiedIcon}
                      aria-hidden
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  ) : (
                    <IconCopy
                      size={DIAL_ICON_SIZE.SM}
                      aria-hidden
                      stroke={DIAL_KIT_ICON_STROKE}
                    />
                  )
                }
                aria-label={copyLabel}
                size={ElementSize.Small}
                onClick={copy}
              />
            </div>
          )}
        </div>
        <div
          className={mergeClasses(
            styles.scrollContainer,
            'max-h-[60vh] overflow-auto',
          )}
          dir="ltr"
        >
          {language ? (
            <Suspense fallback={plainCode}>
              <LazySyntaxHighlighter
                language={language}
                style={syntaxTheme[theme] ?? restrainedSyntaxTheme}
                customStyle={{
                  margin: 0,
                  borderRadius: 0,
                  background: 'transparent',
                  fontSize: 14,
                  lineHeight: 1.5,
                  padding: '14px 16px',
                  letterSpacing: 0,
                }}
                codeTagProps={{ className: codeClassName }}
              >
                {value}
              </LazySyntaxHighlighter>
            </Suspense>
          ) : (
            plainCode
          )}
        </div>
        {/*
         * Copy success leaves no persistent visible text, so it is announced
         * here; the button keeps its stable `copyLabel` accessible name.
         */}
        <span role="status" aria-live="polite" className="sr-only">
          {isCopied ? copiedLabel : ''}
        </span>
      </div>
    );
  },
)

export enum MarkdownTableCopyFormat {
  Csv = 'csv',
  Markdown = 'markdown',
}

serializeMarkdownTableRows = (
  rows: readonly HTMLTableRowElement[],
  format: MarkdownTableCopyFormat,
): string => {
  if (format === MarkdownTableCopyFormat.Csv) {
    return rows.map(serializeCsvRow).join('\n');
  }

  return rows
    .map((row, index) =>
      index === 0
        ? [
            serializeMarkdownRow(row),
            `| ${getCellValues(row)
              .map(() => ':--')
              .join(' | ')} |`,
          ].join('\n')
        : serializeMarkdownRow(row),
    )
    .join('\n');
}

