useCodeCopy = (
  value: string,
  resetDelay = DEFAULT_RESET_DELAY_MS,
): { isCopied: boolean; copy: () => void } => {
  const [isCopied, setIsCopied] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current != null) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const copy = useCallback(() => {
    void copyToClipboard(value).then((success) => {
      if (!success) return;
      if (timeoutRef.current != null) {
        clearTimeout(timeoutRef.current);
      }
      setIsCopied(true);
      timeoutRef.current = setTimeout(() => {
        setIsCopied(false);
      }, resetDelay);
    });
  }, [value, resetDelay]);

  return { isCopied, copy };
}

export interface UseCollapsedTextOptions {
  /** Content identity used to reset long text to the collapsed state when it changes. */
  text: string;
  /** Maximum number of text lines shown while collapsed. */
  collapsedLineCount: number;
}

export interface UseCollapsedTextResult<T extends HTMLElement> {
  /** Ref callback attached to the text element to measure its rendered height. */
  textRef: (node: T | null) => void;
  /** Whether the full text is currently hidden behind the collapsed viewport. */
  isTextCollapsed: boolean;
  /** Whether the measured text is taller than the collapsed viewport. */
  isOverflowing: boolean;
  /** Current collapsed viewport height in pixels. */
  collapsedMaxHeight: number;
  /** Full rendered text height in pixels. */
  expandedMaxHeight: number;
  /** Whether the expanded/collapsed control is currently in the collapsed state. */
  isCollapsed: boolean;
  /** Toggle between expanded and collapsed states. */
  toggleCollapsed: () => void;
}

useCollapsedText = <T extends HTMLElement = HTMLElement>({
  text,
  collapsedLineCount,
}: UseCollapsedTextOptions): UseCollapsedTextResult<T> => {
  const effectiveCollapsedLineCount = Math.max(1, collapsedLineCount);
  const [node, setNode] = useState<T | null>(null);
  const [isCollapsed, setIsCollapsed] = useState(true);
  const [isOverflowing, setIsOverflowing] = useState(false);
  const [collapsedMaxHeight, setCollapsedMaxHeight] = useState(
    DEFAULT_LINE_HEIGHT_FALLBACK * effectiveCollapsedLineCount,
  );
  const [expandedMaxHeight, setExpandedMaxHeight] = useState(0);

  const textRef = useCallback((next: T | null) => {
    setNode(next);
  }, []);

  const measureOverflow = useCallback(() => {
    if (!node) return;

    const computedStyle = window.getComputedStyle(node);
    const parsedFontSize = Number.parseFloat(computedStyle.fontSize);
    const fontSize = Number.isNaN(parsedFontSize) ? 16 : parsedFontSize;
    const parsedLineHeight = Number.parseFloat(computedStyle.lineHeight);
    let lineHeight = fontSize * 1.5;

    if (
      computedStyle.lineHeight !== 'normal' &&
      !Number.isNaN(parsedLineHeight)
    ) {
      lineHeight = computedStyle.lineHeight.endsWith('px')
        ? parsedLineHeight
        : parsedLineHeight * fontSize;
    }

    const nextMaxHeight = lineHeight * effectiveCollapsedLineCount;

    setCollapsedMaxHeight(nextMaxHeight);
    setExpandedMaxHeight(node.scrollHeight);
    setIsOverflowing(node.scrollHeight - nextMaxHeight > OVERFLOW_TOLERANCE);
  }, [node, effectiveCollapsedLineCount]);

  useEffect(() => {
    setIsCollapsed(true);
  }, [effectiveCollapsedLineCount, text]);

  useEffect(() => {
    measureOverflow();

    if (!node || typeof ResizeObserver === 'undefined') return;

    const resizeObserver = new ResizeObserver(measureOverflow);
    resizeObserver.observe(node);

    return () => resizeObserver.disconnect();
  }, [measureOverflow, node, text]);

  const toggleCollapsed = useCallback(() => {
    setIsCollapsed((current) => !current);
  }, []);

  return {
    textRef,
    isTextCollapsed: isCollapsed && isOverflowing,
    isOverflowing,
    collapsedMaxHeight,
    expandedMaxHeight,
    isCollapsed,
    toggleCollapsed,
  };
}

export interface UseAvailableHeightCapOptions {
  /** Pixels left between the element's bottom and the scroller's bottom edge. Defaults to `16`. */
  bottomGap?: number;
  /** Smallest cap to write, so a field below the fold stays usable. Defaults to `200`. */
  minHeight?: number;
  /** Custom property the cap is written to. Defaults to `RESIZABLE_FIELD_MAX_HEIGHT_CSS_VARIABLE`. */
  cssVariable?: string;
}

useAvailableHeightCap = <TElement extends HTMLElement>({
  bottomGap = DEFAULT_BOTTOM_GAP,
  minHeight = DEFAULT_MIN_HEIGHT,
  cssVariable = RESIZABLE_FIELD_MAX_HEIGHT_CSS_VARIABLE,
}: UseAvailableHeightCapOptions = {}): RefObject<TElement | null> => {
  const elementRef = useRef<TElement>(null);

  const measureAvailableHeight = useCallback(() => {
    const element = elementRef.current;

    if (!element) return;

    const scrollContainer = findScrollContainer(element);
    const isDocumentScroller = scrollContainer === document.documentElement;
    const elementTop = element.getBoundingClientRect().top;
    /*
     * A scroll container keeps its own box in place while its content moves, so
     * the element's offset inside that content is its viewport offset relative
     * to the container plus how far the container is scrolled. The document
     * scroller is the exception: its box translates with the scroll, so its
     * rect is already accounted for by `scrollTop` alone.
     */
    const offsetWithinContent = isDocumentScroller
      ? elementTop + scrollContainer.scrollTop
      : elementTop -
        scrollContainer.getBoundingClientRect().top +
        scrollContainer.scrollTop;
    const availableHeight =
      scrollContainer.clientHeight - offsetWithinContent - bottomGap;
    const cap = `${Math.round(Math.max(availableHeight, minHeight))}px`;

    /* Writing the same value again would keep the ResizeObserver below busy. */
    if (element.style.getPropertyValue(cssVariable) === cap) return;

    element.style.setProperty(cssVariable, cap);
  }, [bottomGap, minHeight, cssVariable]);

  useLayoutEffect(() => {
    measureAvailableHeight();

    const element = elementRef.current;

    if (!element) return;

    /*
     * A resize of the scroller changes the cap directly. Content appearing
     * above the element moves it without resizing either one, and no observer
     * reports that, so re-measure when a drag is about to start as well — by
     * then the layout above has settled.
     */
    const resizeObserver =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measureAvailableHeight);

    resizeObserver?.observe(findScrollContainer(element));
    element.addEventListener('pointerdown', measureAvailableHeight, true);
    window.addEventListener('resize', measureAvailableHeight);

    return () => {
      resizeObserver?.disconnect();
      element.removeEventListener('pointerdown', measureAvailableHeight, true);
      window.removeEventListener('resize', measureAvailableHeight);
    };
  }, [measureAvailableHeight]);

  return elementRef;
}

useIsMobile = (): boolean => {
  const [isMobile, setIsMobile] = useState(resolveIsMobile);

  useEffect(() => {
    if (
      typeof window === 'undefined' ||
      typeof window.matchMedia !== 'function'
    )
      return;
    const mql = window.matchMedia(MOBILE_MEDIA_QUERY);
    const onChange = () => setIsMobile(mql.matches);
    mql.addEventListener('change', onChange);
    return () => mql.removeEventListener('change', onChange);
  }, []);

  return isMobile;
}

