export interface UseGridEditingScrollOptions {
  /** Picks the row to scroll to among the rows newly added since the last `rowDataUpdated`. Defaults to the first row flagged `isTemporary`, or the first new row. */
  resolveTargetNode?: (
    newNodes: IRowNode<FileManagerGridRow>[],
  ) => IRowNode<FileManagerGridRow> | null;
}

export interface UseGridEditingScrollResult {
  /** Pass to `DialFileManager`'s `onGridApiChange` prop. */
  handleGridApiChange: (api: GridApi<FileManagerGridRow>) => void;
  /** Re-seeds the known-row-id set without scrolling — call on a data-source change such as a tab switch. */
  reset: () => void;
}

useGridEditingScroll = ({
  resolveTargetNode = defaultResolveTargetNode,
}: UseGridEditingScrollOptions = {}): UseGridEditingScrollResult => {
  const knownRowIdsRef = useRef<Set<string>>(new Set());
  const knownRowIdsInitializedRef = useRef(false);
  const subscribedApiRef = useRef<GridApi<FileManagerGridRow> | null>(null);

  const reset = useCallback(() => {
    knownRowIdsRef.current = new Set();
    knownRowIdsInitializedRef.current = false;
  }, []);

  const handleCellEditingStarted = useCallback(
    (event: CellEditingStartedEvent<FileManagerGridRow>) => {
      const { api } = event;
      if (!api.isDestroyed() && event.rowIndex != null) {
        api.ensureIndexVisible(event.rowIndex);
      }
    },
    [],
  );

  const handleRowDataUpdated = useCallback(
    (event: RowDataUpdatedEvent<FileManagerGridRow>) => {
      const { api } = event;
      const currentIds = new Set<string>();
      const newNodes: IRowNode<FileManagerGridRow>[] = [];

      api.forEachNode((node) => {
        const id = node.data?.id;
        if (!id) return;
        currentIds.add(id);
        if (
          knownRowIdsInitializedRef.current &&
          !knownRowIdsRef.current.has(id)
        ) {
          newNodes.push(node);
        }
      });

      knownRowIdsRef.current = currentIds;
      knownRowIdsInitializedRef.current = true;

      const targetNode = resolveTargetNode(newNodes);
      if (targetNode) {
        scrollRowIntoView(api, targetNode);
      }
    },
    [resolveTargetNode],
  );

  const handleGridApiChange = useCallback(
    (api: GridApi<FileManagerGridRow>) => {
      const previousApi = subscribedApiRef.current;
      if (previousApi === api) return;

      if (previousApi != null) {
        previousApi.removeEventListener(
          'cellEditingStarted',
          handleCellEditingStarted,
        );
        previousApi.removeEventListener('rowDataUpdated', handleRowDataUpdated);
      }

      api.addEventListener('cellEditingStarted', handleCellEditingStarted);
      api.addEventListener('rowDataUpdated', handleRowDataUpdated);
      subscribedApiRef.current = api;
    },
    [handleCellEditingStarted, handleRowDataUpdated],
  );

  useEffect(() => {
    return () => {
      const api = subscribedApiRef.current;
      if (api != null && !api.isDestroyed()) {
        api.removeEventListener('cellEditingStarted', handleCellEditingStarted);
        api.removeEventListener('rowDataUpdated', handleRowDataUpdated);
      }
      subscribedApiRef.current = null;
    };
  }, [handleCellEditingStarted, handleRowDataUpdated]);

  return { handleGridApiChange, reset };
}

export interface OperationLoaderModalProps {
  /** Title shown above the spinner (e.g. "Copying files"). */
  title: string;
  /** Secondary text below the title (e.g. "Copying 2 items"). */
  text: string;
  /** Label for the cancel button. */
  cancelLabel: string;
  /** Called when the user clicks Cancel. */
  onCancel: () => void;
}

export interface UploadProgressModalProps {
  /** Current batch state with per-file entries and open flag. */
  batchState: FileUploadBatchState;
  /** Title shown in the modal header (e.g. "Uploading files"). */
  uploadProgressTitle: string;
  /** Summary text below the title (e.g. "3 of 5 uploaded"). */
  uploadProgressText: string;
  /** Label for the cancel button. */
  cancelLabel: string;
  /** Called when the user clicks Cancel. */
  onCancel: () => void;
}

UploadProgressModal: FC<UploadProgressModalProps> = ({
  batchState,
  uploadProgressTitle,
  uploadProgressText,
  cancelLabel,
  onCancel,
}) => {
  const { files } = batchState;

  const renderDetails = useCallback(
    (name: string, percent?: number): ReactNode => {
      if (percent === undefined) {
        return null;
      }

      /*
       * Named after the file it tracks: a batch renders one bar per row, and
       * bars that share a name tell a screen-reader user nothing about which
       * upload is which.
       */
      return (
        <ProgressBar
          value={percent}
          size={ElementSize.Small}
          aria-label={name}
          data-qa="uploading-indicator"
        />
      );
    },
    [],
  );

  return (
    <Popup
      className="!h-fit !max-h-full !w-[400px] mobile:!w-full desktop:!max-h-[693px]"
      open={batchState.isOpen}
      closeOnOutsideClick={false}
      hideClose
      onClose={onCancel}
      footer={
        <div className="flex justify-end gap-2 px-6 py-4">
          <NeutralButton label={cancelLabel} onClick={onCancel} />
        </div>
      }
      header={
        <div className="flex flex-col gap-2">
          <div>{uploadProgressTitle}</div>
          <div
            className="dial-small-text text-secondary"
            data-qa="uploading-items-count"
          >
            {uploadProgressText}
          </div>
        </div>
      }
    >
      <div className="flex h-full max-h-full flex-col gap-4 px-6">
        <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto">
          {files.map((entry) => (
            <div key={entry.id} className="rounded bg-layer-sunken px-3 py-2">
              <DialFileName
                name={entry.name}
                details={renderDetails(entry.name, entry.percent)}
              />
            </div>
          ))}
        </div>
      </div>
    </Popup>
  );
}

