normalizePersistedHtmlTagAttachmentType = (
  annotation: Annotation,
): Annotation => {
  if (annotation.target?.selector?.type !== 'html_tag') return annotation;

  const attachment = annotation.body?.source?.attachment;
  if (attachment?.url == null) return annotation;

  const inferredType = inferCitationMimeTypeFromPath(attachment.url);
  if (inferredType == null || inferredType === attachment.type) {
    return annotation;
  }

  return {
    ...annotation,
    body: {
      ...annotation.body,
      source: {
        ...annotation.body?.source,
        type: 'attachment',
        attachment: { ...attachment, type: inferredType },
      },
    },
  };
}

normalizeRawAnnotations = (
  rawAnnotations: unknown[],
  attachments: MessageAttachment[],
): Annotation[] =>
  rawAnnotations.flatMap((raw) => {
    if (typeof raw !== 'object' || raw === null) return [];
    const r = raw as Record<string, unknown>;

    const htmlTagAnnotation = normalizeHtmlTagAnnotation(r);
    if (htmlTagAnnotation) return [htmlTagAnnotation];

    const attachmentIndexAnnotation = normalizeAttachmentIndexAnnotation(
      r,
      attachments,
    );
    if (attachmentIndexAnnotation) return [attachmentIndexAnnotation];

    return [];
  })

stripTrailingDots = (name: string): string => {
  let end = name.length;

  while (end > 0 && name[end - 1] === '.') {
    end -= 1;
  }

  return name.slice(0, end);
}

truncateToUtf8Bytes = (str: string, maxBytes: number): string => {
  const encoded = encoder.encode(str);
  if (encoded.length <= maxBytes) return str;

  /*
   * UTF-8 continuation bytes have the high bits `10xxxxxx` (0x80-0xBF);
   * back up from maxBytes to the start of the char it would otherwise split.
   */
  let end = maxBytes;
  while (end > 0 && (encoded[end] & 0xc0) === 0x80) {
    end -= 1;
  }
  return decoder.decode(encoded.subarray(0, end));
}

export function mergeClasses(...inputs: Parameters<typeof classNames>): string {
  return twMerge(classNames(...inputs));
}

buildCssVars = (
  vars: Record<string, string | number | undefined>,
): CSSProperties => {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(vars)) {
    if (value !== undefined && value !== '') {
      result[key] = String(value);
    }
  }
  return result as CSSProperties;
}

isStatusMessage = (
  msg: Message | StatusMessage,
): msg is StatusMessage => msg.role === MessageRole.Status

